import csv
import json
import argparse
from datetime import datetime, timezone

def parse_timestamp(ts_str):
    # Handle 'Z' suffix by replacing it with '+00:00'
    if ts_str.endswith('Z'):
        ts_str = ts_str[:-1] + '+00:00'
    return datetime.fromisoformat(ts_str)

def main():
    parser = argparse.ArgumentParser(
        description='Process payment transactions from a CSV file and produce a JSON summary.'
    )
    parser.add_argument('csv_file', help='Path to the input CSV file.')
    args = parser.parse_args()

    transactions = {}
    with open(args.csv_file, mode='r', newline='', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row_num, row in enumerate(reader):
            try:
                tx_id = row['tx_id']
                timestamp_str = row['timestamp']
                amount = int(row['amount'])
                status = row['status']

                current_timestamp = parse_timestamp(timestamp_str)

                if tx_id not in transactions:
                    transactions[tx_id] = {
                        'timestamp': current_timestamp,
                        'amount': amount,
                        'status': status,
                        'original_row_num': row_num # For tie-breaking
                    }
                else:
                    existing_tx = transactions[tx_id]
                    existing_timestamp = existing_tx['timestamp']

                    if current_timestamp > existing_timestamp:
                        # New record is chronologically later
                        transactions[tx_id] = {
                            'timestamp': current_timestamp,
                            'amount': amount,
                            'status': status,
                            'original_row_num': row_num
                        }
                    elif current_timestamp == existing_timestamp:
                        # Same instant, retain the one appearing later in CSV
                        if row_num > existing_tx['original_row_num']:
                            transactions[tx_id] = {
                                'timestamp': current_timestamp,
                                'amount': amount,
                                'status': status,
                                'original_row_num': row_num
                            }

            except (ValueError, KeyError) as e:
                # Optionally handle malformed rows, for this task we assume valid input format
                pass

    total_valid_amount = 0
    valid_count = 0
    failed_count = 0

    for tx_id, tx_data in transactions.items():
        status = tx_data['status']
        amount = tx_data['amount']

        if status == 'VALID':
            total_valid_amount += amount
            valid_count += 1
        elif status == 'FAILED':
            failed_count += 1
        # PENDING transactions are excluded

    output = {
        'total_valid_amount': total_valid_amount,
        'valid_count': valid_count,
        'failed_count': failed_count
    }

    print(json.dumps(output))

if __name__ == '__main__':
    main()
